#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int MAXN = 32;
const int MAXB = 60;
const int MOD = 1e9 + 7;
const ll INF = 2e18;

inline void adjust(int &a)
{
    if (a >= MOD)
        a -= MOD;
    else if (a < 0)
        a += MOD;
}

struct Matrix
{
    int val[MAXN][MAXN];
    int size;
    Matrix(int n=0, int x=0)
    {
        size = n;
        for (int i=0; i<size; i++)
            for (int j=0; j<size; j++)
                val[i][j] = (i == j) ? x : 0;
    }
    int* operator[](int row)
    {
        return val[row];
    }
    Matrix operator*(const Matrix &b)
    {
        Matrix result(size, 0);
        for (int i=0; i<size; i++)
            for (int j=0; j<size; j++)
                for (int k=0; k<size; k++)
                    adjust(result[i][k] += (ll)val[i][j] * b[j][k] % MOD);
        return result;
    }
    Matrix operator+(const Matrix &b)
    {
        Matrix sum(size, 0);
        for (int i=0; i<size; i++)
            for (int j=0; j<size; j++)
                sum[i][j] = val[i][j] + b[i][j];
        return sum;
    }
    bool operator==(const Matrix &b)
    {
        if (size != b.size) return false;
        for (int i=0; i<size; i++)
            for (int j=0; j<size; j++)
                if (val[i][j] != b[i][j]) return false;
        return true;
    }
};

Matrix power(Matrix base, ll exponent)
{
    Matrix result(base.size, 1);
    while (exponent)
    {
        if (exponent & 1)
            result = result * base;
        base = base * base;
        exponent >>= 1;
    }
    return result;
}

int main()
{
