        Matrix tmp = a[i-1];
        a[i] = a[i-1];
        for (int j=1; j<k; j++)
        {
            a[i] = a[i] * shift[k-1];
            a[i] = a[i] * tmp;
        }
        a[i] = a[i] * shift[k-1];
    }

    Matrix answer(k+1);
    answer[0][k] = 1;
    answer = answer * get(n, lastIndex - 1);

    int result = 0;
    for (int i=0; i<=k; i++)
        adjust(result += answer[0][i]);

    cout << result << "\n";
}
